package cn.adc.dental;

import java.time.*;
import java.util.*;

/** Production-shared migration/lineage policy checks only. No JDBC mocks or transaction simulation. */
public class ReminderMigrationChainCheck {
    private static final List<Map<String,Object>> checks=new ArrayList<>();
    private static final Instant NOW=Instant.parse("2026-10-22T12:00:00Z");
    private static void check(String name,boolean ok){checks.add(Map.of("name",name,"passed",ok));if(!ok)throw new AssertionError(name);}
    private static void reject(String name,int status,String code,Runnable run){try{run.run();throw new AssertionError(name+" accepted");}catch(ApiError e){check(name,e.status==status&&e.code.equals(code));}}
    private static ReminderRules.Business b(String phone){return new ReminderRules.Business(ReminderRules.Kind.APPOINTMENT,30,10,2,null,NOW.plusSeconds(7200),null,phone);}
    private static ReminderRules.Settings s(Integer lead,boolean inApp,boolean sms){return new ReminderRules.Settings(lead,1,"09:00:00",inApp,sms);}
    private static ReminderRules.Draft draft(ReminderRules.Business b,ReminderRules.Settings s,String channel){return ReminderRules.plan(b,s,NOW,List.of()).actions().stream().filter(a->a.channel().equals(channel)&&a.draft()!=null).findFirst().orElseThrow().draft();}
    private static ReminderRules.History h(long id,ReminderRules.Draft d,String status,Instant sent){return new ReminderRules.History(id,true,d.channel(),d.plannedAt(),d.recipient(),d.content(),status,sent);}
    private static ReminderLifecycleRules.Scoped ancestor(ReminderRules.History h){return new ReminderLifecycleRules.Scoped(20,h);}
    private static long count(ReminderMigrationRules.Evaluation e,String op){return e.result().actions().stream().filter(a->a.operation().equals(op)).count();}
    private static ReminderMigrationRules.Evaluation plan(ReminderRules.Business b,ReminderRules.Settings s,List<ReminderRules.History> own,List<ReminderLifecycleRules.Scoped> chain,boolean complete){return ReminderMigrationRules.evaluateChain(b,s,NOW,own,chain,complete);}
    public static void main(String[] args){var report=new LinkedHashMap<String,Object>();report.put("mode","no-db-no-http");report.put("startedAt",Instant.now().toString());boolean passed=false;try{run();passed=true;}catch(Throwable e){report.put("error",e.getClass().getSimpleName()+": "+e.getMessage());}report.put("status",passed?"passed":"failed");report.put("checks",checks);report.put("finishedAt",Instant.now().toString());System.out.println(Store.encode(report));if(!passed)System.exit(1);}
    private static void run(){
        var business=b("10000000000");var both=s(60,true,true);var station=s(60,true,false);var d=draft(business,both,"站内");var sms=draft(business,both,"短信");
        check("closure business count deduplicates local and guard appointment",ReminderMigrationRules.businessCount(List.of("APPOINTMENT:30"),List.of(20L,30L,20L))==2);
        check("equal numeric plan and appointment IDs remain distinct businesses",ReminderMigrationRules.businessCount(List.of("FOLLOWUP:30"),List.of(30L))==2);
        var fifty=new ArrayList<Long>();for(long n=1;n<=50;n++)fifty.add(n);check("all fifty guard businesses fit only when complete",ReminderMigrationRules.businessCount(List.of("APPOINTMENT:30"),fifty)==50);fifty.add(51L);reject("last extra readonly predecessor rejects rather than truncates",413,"MIGRATION_SCOPE_TOO_LARGE",()->ReminderMigrationRules.businessCount(List.of("APPOINTMENT:30"),fifty));
        reject("foreign history counts toward five hundred bound",413,"MIGRATION_SCOPE_TOO_LARGE",()->ReminderMigrationRules.limit("关联历史",501,500));reject("foreign parent counts toward two hundred bound",413,"MIGRATION_SCOPE_TOO_LARGE",()->ReminderMigrationRules.limit("父资源",201,200));
        var clean=plan(business,both,List.of(),List.of(),true);check("complete ordinary successor now migrates without blanket refusal",!clean.blocked()&&count(clean,"CREATE")==2);
        var sent=h(101,d,"已发送",NOW.minusSeconds(1));var guarded=plan(business,both,List.of(),List.of(ancestor(sent)),true);check("readonly predecessor same content only suppresses same channel",!guarded.blocked()&&count(guarded,"CREATE")==1&&guarded.result().actions().getFirst().channel().equals("短信"));
        check("readonly predecessor message identity not returned as action",guarded.result().actions().stream().noneMatch(a->Objects.equals(a.messageId(),101L)));
        check("semantic action list does not expose readonly predecessor ID",guarded.semantic().stream().noneMatch(a->Objects.equals(a.get("messageId"),"101")));
        var changed=new ReminderRules.Draft("站内",d.plannedAt(),d.recipient(),"不同的旧时间内容",false);check("different sent content does not suppress new ordinary successor",count(plan(business,station,List.of(),List.of(ancestor(h(102,changed,"已发送",NOW.minusSeconds(1)))),true),"CREATE")==1);
        for(String state:List.of("发送中","失败")){var e=plan(business,both,List.of(),List.of(ancestor(h(103,d,state,null))),true);check(state+" chain guard suppresses affected channel and migration remains atomic blocked",e.blocked()&&e.result().reconciliation()&&count(e,"CREATE")==1&&e.result().actions().stream().noneMatch(a->a.channel().equals("站内")&&a.operation().equals("CREATE")));check(state+" foreign record never appears as writable action",e.result().actions().stream().noneMatch(a->Objects.equals(a.messageId(),103L)));}
        var unknown=ancestor(h(104,d,"发送中",null));check("explicit channel close still cannot clear unknown result",plan(business,s(null,false,false),List.of(),List.of(unknown),true).blocked());
        var mismatch=new ReminderRules.History(105,false,"站内",d.plannedAt(),d.recipient(),d.content(),"待发送",null);check("wrong ownership in guard history blocks whole migration",plan(business,station,List.of(),List.of(ancestor(mismatch)),true).blocked());
        check("incomplete chain cannot commit even with no known messages",plan(business,station,List.of(),List.of(),false).blocked());
        var own=h(201,d,"待发送",null);var scopedOwn=new ReminderLifecycleRules.Scoped(30,own);var reuse=plan(business,station,List.of(own),List.of(scopedOwn),true);check("matching local pending stable identity retained",!reuse.blocked()&&count(reuse,"REUSE")==1&&reuse.result().actions().getFirst().messageId()==201);
        var dedup=plan(business,station,List.of(own),List.of(scopedOwn,ancestor(sent)),true);check("sent predecessor retires only local redundant pending",!dedup.blocked()&&count(dedup,"CANCEL")==1&&dedup.result().actions().getFirst().messageId()==201);
        var oldCanceled=h(202,d,"已取消",null);var noRestore=plan(business,station,List.of(oldCanceled),List.of(new ReminderLifecycleRules.Scoped(30,oldCanceled),ancestor(sent)),true);check("sent ancestor prevents blind local canceled restoration",!noRestore.blocked()&&count(noRestore,"RESTORE")==0);
        var missingSms=plan(b(null),both,List.of(),List.of(ancestor(h(106,sms,"已发送",NOW.minusSeconds(1)))),true);check("already sent same SMS independently suppresses missing current phone",!missingSms.blocked()&&!missingSms.result().issues().contains("SMS_RECIPIENT_MISSING")&&count(missingSms,"CREATE")==1);
        check("sent in-app cannot satisfy missing SMS recipient",plan(b(null),both,List.of(),List.of(ancestor(sent)),true).blocked());
        var unknownSms=ancestor(h(107,sms,"失败",null));check("sent SMS does not erase separate unknown SMS result",plan(b(null),both,List.of(),List.of(ancestor(h(106,sms,"已发送",NOW.minusSeconds(1))),unknownSms),true).blocked());
        var clear=plan(business,s(null,true,true),List.of(own),List.of(scopedOwn),true);check("explicit lead clear stays authorized unscheduled and cancels only local pending",!clear.blocked()&&count(clear,"CANCEL")==1&&clear.result().issues().contains("EXPLICIT_UNSCHEDULED"));
        var pendingAncestor=ancestor(h(108,d,"待发送",null));var pendingBlock=plan(business,both,List.of(),List.of(pendingAncestor),true);check("readonly known pending cannot be canceled across scope or duplicated",pendingBlock.blocked()&&count(pendingBlock,"CREATE")==1&&pendingBlock.result().issues().contains("CHAIN_GUARD_PENDING_REQUIRES_OWNER:站内"));
        var localAncestor=ReminderMigrationRules.evaluateChain(business,both,NOW,List.of(),List.of(pendingAncestor),true,Set.of(20L,30L));check("local editable predecessor cleanup remains part of same transaction plan",!localAncestor.blocked()&&count(localAncestor,"CREATE")==2);
        var retired=new ReminderRules.Business(ReminderRules.Kind.APPOINTMENT,30,10,2,"APPOINTMENT_STARTED_OR_INVALID",NOW.minusSeconds(1),null,null);check("readonly live descendant pending does not block terminal local cleanup without new plan",!plan(retired,both,List.of(),List.of(pendingAncestor),true).blocked());
        var create=clean.result().actions().getFirst();ReminderMigrationRules.localAction(2,business,create,null,false);check("new planned message permitted only for local writable business",true);reject("cannot create for foreign business",409,"MIGRATION_ACTION_SCOPE_INVALID",()->ReminderMigrationRules.localAction(1,business,create,null,false));
        var cancel=dedup.result().actions().getFirst();ReminderMigrationRules.localAction(2,business,cancel,2L,true);check("local related known pending cancellation permitted",true);reject("cannot mutate foreign-clinic annotated message",409,"MIGRATION_ACTION_SCOPE_INVALID",()->ReminderMigrationRules.localAction(2,business,cancel,1L,true));reject("cannot mutate unrelated message in same clinic",409,"MIGRATION_ACTION_SCOPE_INVALID",()->ReminderMigrationRules.localAction(2,business,cancel,2L,false));
        var immediate=s(180,true,false);var first=plan(business,immediate,List.of(),List.of(),true);var later=ReminderMigrationRules.evaluateChain(business,immediate,NOW.plusSeconds(60),List.of(),List.of(),true);check("AT_COMMIT semantic stable across actual commit time",ReminderMigrationRules.digest(first.semantic()).equals(ReminderMigrationRules.digest(later.semantic())));
        check("foreign history content change changes dependency digest",!ReminderMigrationRules.digest(Map.of("guard",sent)).equals(ReminderMigrationRules.digest(Map.of("guard",h(101,changed,"已发送",NOW.minusSeconds(1))))));
        var resources=new LinkedHashMap<String,Collection<Long>>();resources.put("reminder_messages",List.of(99L,1L));resources.put("appointments",List.of(30L,20L));resources.put("patients",List.of(10L));resources.put("clinics",List.of(2L,1L));resources.put("dentists",List.of(8L,7L));var order=ReminderMigrationRules.lockOrder(resources);check("foreign and local resources still global category and ID ordered",order.getFirst().equals(new ReminderMigrationRules.Lock("clinics",1))&&order.get(1).equals(new ReminderMigrationRules.Lock("clinics",2))&&order.getLast().equals(new ReminderMigrationRules.Lock("reminder_messages",99)));
    }
}
